12	    private static void bfsComponent(List<List<Integer>> adjacencyList, int source, boolean[] visited, List<Integer> result) {
13	        Deque<Integer> queue = new ArrayDeque<>();
14	        visited[source] = true;
15	        queue.addLast(source);
16	
17	        while (!queue.isEmpty()) {
18	            int current = queue.removeFirst();
19	            result.add(current);
20	
21	            for (int neighbor : adjacencyList.get(current)) {
22	                if (!visited[neighbor]) {
23	                    visited[neighbor] = true;
24	                    queue.addLast(neighbor);
25	                }
26	            }
27	        }
28	    }
