30	    static List<Integer> bfs(List<List<Integer>> adjacencyList) {
31	        int vertexCount = adjacencyList.size();
32	        boolean[] visited = new boolean[vertexCount];
33	        List<Integer> result = new ArrayList<>(vertexCount);
34	
35	        for (int vertex = 0; vertex < vertexCount; vertex++) {
36	            if (!visited[vertex]) {
37	                bfsComponent(adjacencyList, vertex, visited, result);
38	            }
39	        }
40	        return result;
41	    }
